// İkonların hepsi sayfaya bir kez gizli <symbol> olarak eklenir, her yerde <use> ile çağrılır
G.ikonlariYukle = function () {
  var h = '<svg xmlns="http://www.w3.org/2000/svg" style="display:none">';
  for (var k in G.IKONLAR) h += '<symbol id="i-' + k + '" viewBox="0 0 512 512">' + G.IKONLAR[k] + '</symbol>';
  var kap = document.createElement('div');
  kap.innerHTML = h + '</svg>';
  document.body.insertBefore(kap.firstChild, document.body.firstChild);
};

// Arayüz metinlerinde kullanım: G.ikon('iksir'), G.ikon('iksir', 'ek-sinif') veya G.ikon('iksir', '', '#c0503a') (renkli)
G.ikon = function (ad, sinif, renk) {
  return '<svg class="ikon' + (sinif ? ' ' + sinif : '') + '"' + (renk ? ' style="color:' + renk + '"' : '') +
    ' aria-hidden="true"><use href="#i-' + ad + '"></use></svg>';
};

G.ikonlariYukle();

// veri.js'te "simge" alanı olan canavar, sınıf ve sarf malzemelerinin ikon'u SVG'ye çevrilir.
// Sarf malzemeleri kendi "renk" değeriyle boyanır (Can İksiri kırmızı, Rün Özü turuncu...).
// (Arayüz her yerde .ikon'u bastığı için başka bir değişiklik gerekmez. simge yoksa eski emoji kalır.)
G.simgeleriUygula = function (liste, sinif, renkli) {
  for (var k in liste) if (liste[k].simge) liste[k].ikon = G.ikon(liste[k].simge, sinif, renkli ? liste[k].renk : '');
};
G.simgeleriUygula(G.CANAVARLAR, 'canavar-ikon');
G.simgeleriUygula(G.SINIFLAR, 'sinif-ikon');
G.simgeleriUygula(G.SARF, 'sarf-ikon', true);
// Dükkandaki ürünler aynı sarf malzemesinin ikonunu kullanır
G.DUKKAN.forEach(function (u) { if (G.SARF[u.t] && G.SARF[u.t].simge) u.ikon = G.SARF[u.t].ikon; });
// Altın her yerde aynı: G.IK_PARA
G.IK_PARA = G.ikon('altin', 'para-ikon');
